#!/usr/bin/env python3
"""A minimal UCI engine that intentionally evaluates every position as winning for Black
(-1000 centipawns for White) and plays random legal moves (so weak)."""
import sys
import chess
import random

def write(line):
    sys.stdout.write(line + "\n")
    sys.stdout.flush()

def main():
    board = chess.Board()
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == "uci":
            write("id name GiveawayEngine")
            write("id author ChatGPT")
            write("uciok")
        elif line == "isready":
            write("readyok")
        elif line.startswith("ucinewgame"):
            board.reset()
        elif line.startswith("position"):
            parts = line.split()
            idx = 1
            if parts[idx] == "startpos":
                board.reset()
                idx += 1
            elif parts[idx] == "fen":
                fen = " ".join(parts[idx + 1: idx + 7])
                board.set_fen(fen)
                idx += 7
            if idx < len(parts) and parts[idx] == "moves":
                for mv in parts[idx + 1:]:
                    try:
                        board.push_uci(mv)
                    except Exception:
                        pass
        elif line.startswith("go"):
            # Provide a dummy evaluation that is very good for Black (-1000 cp)
            write("info depth 1 score cp -1000")
            move = None
            for m in board.legal_moves:
                move = m
                break
            if move is None:
                write("bestmove 0000")
            else:
                write(f"bestmove {move.uci()}")
                board.push(move)
        elif line == "quit":
            break
        elif line.startswith("setoption"):
            # Ignore any options
            continue
    sys.exit(0)

if __name__ == "__main__":
    main()
